(49411, 'Psalms 3:6', 'Psalms', 3, 6, 'نه وېرېږم له زرګونو دښمنانو چې راتاو له هرې خوا نه دي پر ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms3_verse_6.mp3', '', 1761754199, 1761754199),
(49412, 'Psalms 3:7', 'Psalms', 3, 7, 'ای څښتنه زما پاڅه! ومې ژغوره زما خدایه ژامې ماتې کړه زما د دښمنانو او غاښونه وباسه د بدکارانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms3_verse_7.mp3', '', 1761754199, 1761754199),
(49413, 'Psalms 3:8', 'Psalms', 3, 8, 'د څښتن له خوا خلاصون ورکول کیږي په خپل قوم باندې دې وي ستا برکت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms3_verse_8.mp3', '', 1761754199, 1761754199),
(49414, 'Jeremiah 24:1', 'Jeremiah', 24, 1, 'وروستو د دې نه چې د بابل بادشاه نبوکدنضر د يهوياکين د يهويقيم زوئ د يهوداه بادشاه بابل ته سره د آفسرانو، کاريګرانو او لوهارانو قېديان بوتلل نو بيا مالِک خُدائ ما ته په رويا کښې د اينځرو دوه ټوکرۍ راوښودلې چې د مالِک خُدائ د کور مخې ته پرتې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_1.mp3', '', 1761754199, 1761754199),
(49415, 'Jeremiah 24:2', 'Jeremiah', 24, 2, 'په يوه ټوکرۍ کښې اول موسمى او پاخۀ اينځر وُو، او په بله ټوکرۍ کښې خراب اينځر وُو، دومره ډېر خراب چې د خوړلو نۀ وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_2.mp3', '', 1761754199, 1761754199),
(49416, 'Jeremiah 24:3', 'Jeremiah', 24, 3, 'نو بيا مالِک خُدائ ما ته وفرمائيل، ”يرمياه تا ته څۀ ښکارى؟“ ما ورته په جواب کښې ووئيل، ”اينځر. ښۀ اينځر ډېر ښۀ دى خو خراب اينځر ډېر خراب دى، دومره خراب دى چې د خوړلو قابل هم نۀ دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_3.mp3', '', 1761754199, 1761754199),
(49417, 'Jeremiah 24:4', 'Jeremiah', 24, 4, 'نو بيا د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_4.mp3', '', 1761754199, 1761754199),
(49418, 'Jeremiah 24:5', 'Jeremiah', 24, 5, '”مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، دا ښۀ اينځر د يهوداه د هغه خلقو په شان دى چې ما د بابل مُلک ته د دې ځائ نه جلاوطن کړى دى او زۀ هغوئ ته هم دغه شان ښۀ ګورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_5.mp3', '', 1761754199, 1761754199),
(49419, 'Jeremiah 24:6', 'Jeremiah', 24, 6, 'زۀ به هغوئ ته په ښۀ سترګه ګورم، او زۀ به هغوئ دې مُلک ته واپس راولم. زۀ به هغوئ آباد کړم او زۀ به هغوئ ونۀ غورزوم، زۀ به هغوئ وکرم او د بېخ نه به يې نۀ راوباسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_6.mp3', '', 1761754199, 1761754199),
(49420, 'Jeremiah 24:7', 'Jeremiah', 24, 7, 'زۀ به هغوئ له دا خواهش ورکړم چې هغوئ ما وپېژنى چې زۀ مالِک خُدائ يم. هغوئ به زما مخلوق وى، او زۀ به د هغوئ خُدائ پاک يم، ځکه چې هغوئ به په پوره زړۀ سره ما ته رجوع وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_7.mp3', '', 1761754199, 1761754199),
(49421, 'Jeremiah 24:8', 'Jeremiah', 24, 8, 'مالِک خُدائ وفرمائيل، هغه خراب اينځر چې دومره ډېر خراب دى چې د خوړلو قابل هم نۀ دى، نو دغه شان به زۀ د صدقياه د يهوداه بادشاه، او د هغۀ د آفسرانو سره څوک چې د يروشلم نه ژوندى پاتې شوى دى کۀ هغه دلته اوسيږى او يا کۀ په مِصر کښې دى دغه شان سلوک وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_8.mp3', '', 1761754199, 1761754199),
(49422, 'Jeremiah 24:9', 'Jeremiah', 24, 9, 'زۀ به هغوئ په زمکه د هر يو مُلک دپاره د دهشت مثال او د افت زده ګانو نمونه وګرځوم. زۀ چې هغوئ چرته هم خوارۀ کړم نو هغوئ به د عبرت يو مثال جوړ شى او خلق به د هغوئ نوم د بې‌عزتۍ دپاره استعمالوى او د هغوئ بې‌عزتى به کوى او لعنت به پرې وائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_9.mp3', '', 1761754199, 1761754199),
(49423, 'Jeremiah 24:10', 'Jeremiah', 24, 10, 'زۀ به په هغوئ جنګ راولم، لوږه او وبا به پرې راولم، تر هغې پورې چې هغوئ به په هغه مُلک کښې ختم کړم کوم چې ما دوئ او د دوئ پلار نيکۀ له ورکړے وو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah24_verse_10.mp3', '', 1761754199, 1761754199),
(49424, 'Psalms 139:1', 'Psalms', 139, 1, 'ای څښتنه، زه ازمایلی یم تا او ما پېژنې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_1.mp3', '', 1761754199, 1761754199),
(49425, 'Psalms 139:2', 'Psalms', 139, 2, 'کله چې زه کوم ارام او یا کار کومه نو ته خبرېږې پرې ته د لېرې نه پوهېږې په فکرونو زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_2.mp3', '', 1761754199, 1761754199),
(49426, 'Psalms 139:3', 'Psalms', 139, 3, 'ته مې ښه وینې که زه ګرځم او که ملاست یم ټولو اعمالو نه خبر یې زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_3.mp3', '', 1761754199, 1761754199),
(49427, 'Psalms 139:4', 'Psalms', 139, 4, 'خبره نه وي لا وتلې مې د خولې نه ته پرې بیخي پوهېږې ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_4.mp3', '', 1761754199, 1761754199),
(49428, 'Psalms 139:5', 'Psalms', 139, 5, 'د کټارې په شان زما نه ته چاپېر یې خپل لاس دې ایښی وي زما په سر باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_5.mp3', '', 1761754199, 1761754199),
(49429, 'Psalms 139:6', 'Psalms', 139, 6, 'داسې معلومات چې ته یې لرې زما په هکله حیرانوونکی دی ډېر زما د عقل نه اوچت دی دا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_6.mp3', '', 1761754199, 1761754199),
(49430, 'Psalms 139:7', 'Psalms', 139, 7, 'وتښتم چېرته ستا نه؟ ستا له حضوره چېرته لېرې لاړ شم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_7.mp3', '', 1761754199, 1761754199),
(49431, 'Psalms 139:8', 'Psalms', 139, 8, 'که چېرې وخېژم اسمان ته نو ته یې هلته که زه څملم د مړو دنیا کې نو ته یې هلته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_8.mp3', '', 1761754199, 1761754199),
(49432, 'Psalms 139:9', 'Psalms', 139, 9, 'که ما کولای شول چې والوزمه هغه ځای ته چې په کې لمر راخېژي یا مې کولای شول چې واوسېږم هغه ځای کې چېرته چې لمر پرېوځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_9.mp3', '', 1761754199, 1761754199),
(49433, 'Psalms 139:10', 'Psalms', 139, 10, 'هلته به هم یې چې ماته وکړې لارښوونه ته به هلته یې چې ما سره کومک وکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_10.mp3', '', 1761754199, 1761754199),
(49434, 'Psalms 139:11', 'Psalms', 139, 11, 'که زه ووایم تیارې نه چې ما پټ کړي یا رڼا نه چې شاوخوا مې ده بدله په تیاره شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_11.mp3', '', 1761754199, 1761754199),
(49435, 'Psalms 139:12', 'Psalms', 139, 12, 'خو حتی تیاره هم تاته نه ده تیاره او شپه د ستا دپاره ده د رڼا ورځې په شان ځکه تاته رڼا او تیاره یوشان دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_12.mp3', '', 1761754199, 1761754199),
(49436, 'Psalms 139:13', 'Psalms', 139, 13, 'تا جوړه کړې هره برخه د بدن ده زما هغه دې ټولې یوځای کړې زما د مور ګېډه کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_13.mp3', '', 1761754199, 1761754199),
(49437, 'Psalms 139:14', 'Psalms', 139, 14, 'ثنا او صفت کومه ستا ځکه چې زه دې پیدا کړی یمه په عجیبه او په مرموزه توګه او په دې خاطر چې ټول کارونه عجیبه دي ستا په دې ډېر ښه پوهېږم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_14.mp3', '', 1761754199, 1761754199),
(49438, 'Psalms 139:15', 'Psalms', 139, 15, 'چې کله هډوکي جوړېدل زما یوځای کېدل هغه په غور سره زما د مور ګېډه کې چې لویېدمه پټ په هغه ځای کې ته پوهېدلې چې زه هلته ومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_15.mp3', '', 1761754199, 1761754199),
(49439, 'Psalms 139:16', 'Psalms', 139, 16, 'مخکې له دې نه چې پیدا شمه زه تا لیدلی ؤ زما نامکمله بدن تا زما د ژوند ورځې چې دې ټاکلې وې زما دپاره ټولې لیکلې دې وې په خپل کتاب کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_16.mp3', '', 1761754199, 1761754199),
(49440, 'Psalms 139:17', 'Psalms', 139, 17, 'څومره قیمتي دي ستا فکرونه زما دپاره خدایه څومره زیات دي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_17.mp3', '', 1761754199, 1761754199),
(49441, 'Psalms 139:18', 'Psalms', 139, 18, 'که زه یې وشمېرمه نو وي به زیات هغه له شګو څخه چې رابېدار شمه زه نو بیاهم تا سره یم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_18.mp3', '', 1761754199, 1761754199),
(49442, 'Psalms 139:19', 'Psalms', 139, 19, 'ای خدایه، کاشکې ته ووژنې بدکاره خلک کاشکې پرېږدي قاتلان خلک ما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_19.mp3', '', 1761754199, 1761754199),
(49443, 'Psalms 139:20', 'Psalms', 139, 20, 'بدې خبرې کوي دوی تا پسې او ستا دښمنان غلطه ګټه اخلي ستا د نامه څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_20.mp3', '', 1761754199, 1761754199),
(49444, 'Psalms 139:21', 'Psalms', 139, 21, 'ای څښتنه، ایا ونه کړم کرکه هغه چا نه چې کوي کرکه تا نه؟ او بېزاره نه شم هغه چا نه چې سرکښي کړي تا نه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_21.mp3', '', 1761754199, 1761754199),
(49445, 'Psalms 139:22', 'Psalms', 139, 22, 'بیخي نفرت کوم هغوی نه هغوی ګڼمه لکه خپل دښمنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_22.mp3', '', 1761754199, 1761754199),
(49446, 'Psalms 139:23', 'Psalms', 139, 23, 'ای خدایه، ته ما وازمایه او زما له زړه خبر شه ما امتحان کړه او شه خبر له اندېښنو نه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_23.mp3', '', 1761754199, 1761754199),
(49447, 'Psalms 139:24', 'Psalms', 139, 24, 'وګوره ماته که روان یم زه په بده لاره او د تل ژوندون په لاره وکړه لارښوونه زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms139_verse_24.mp3', '', 1761754199, 1761754199),
(49448, 'Deuteronomy 31:1', 'Deuteronomy', 31, 1, 'موسی د اسراییلو د قوم سره خپلو خبرو ته دوام ورکړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_1.mp3', '', 1761754199, 1761754199),
(49449, 'Deuteronomy 31:2', 'Deuteronomy', 31, 2, 'او ویې ویل: «زه اوس د یوسلو شل کالو په عمر یم او نور د دې توان نه لرم چې ستاسو مشري وکړم او څښتن ماته ویلي دي چې ته به د اردن د سیند څخه تېر نه شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_2.mp3', '', 1761754199, 1761754199),
(49450, 'Deuteronomy 31:3', 'Deuteronomy', 31, 3, 'ستاسو څښتن خدای به په خپله ستاسو په مخکې روان وي او هغه قومونه به چې هلته اوسیږي له منځه یوسي، ترڅو تاسو د هغوی خاوره ونیسئ. لکه څنګه چې څښتن ویلي دي، یوشع به ستاسو مشر وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_3.mp3', '', 1761754199, 1761754199),
(49451, 'Deuteronomy 31:4', 'Deuteronomy', 31, 4, 'څښتن به هغه خلک داسې له منځه یوسي لکه څنګه چې هغه د اموریانو پاچاهانو سیحون او عوج ته ماتې ورکړه او د هغوی هېواد یې وران کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_4.mp3', '', 1761754199, 1761754199),
(49452, 'Deuteronomy 31:5', 'Deuteronomy', 31, 5, 'څښتن به تاسو ته په هغوی باندې بری درکړي او تاسو باید د هغوی سره هماغه شان عمل وکړئ لکه څنګه چې ما درته ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_5.mp3', '', 1761754199, 1761754199),
(49453, 'Deuteronomy 31:6', 'Deuteronomy', 31, 6, 'قوي او زړور اوسئ. د هغوی څخه مه وېرېږئ. ستاسو څښتن خدای به تل ستاسو سره روان وي او تاسو به هېڅکله یوازې نه پرېږدي او تاسو به نه هېروي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_6.mp3', '', 1761754199, 1761754199),
(49454, 'Deuteronomy 31:7', 'Deuteronomy', 31, 7, 'بیا موسی یوشع راوغوښت او د اسراییلو د ټول قوم په حضور کې یې ورته وویل: «قوي او زړور اوسه. د هغې خاورې په نیولو کې به ته د دغو خلکو مشري کوې چې څښتن یې د هغوی د نیکونو سره وعده کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_7.mp3', '', 1761754199, 1761754199),
(49455, 'Deuteronomy 31:8', 'Deuteronomy', 31, 8, 'څښتن به په خپله تاته لارښوونه کوي او درسره مل به وي. هغه به ستا سره مرسته کوي او تا به یوازې نه پرېږدي. نو جرات له لاسه مه ورکوه او مه وېرېږه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_8.mp3', '', 1761754199, 1761754199),
(49456, 'Deuteronomy 31:9', 'Deuteronomy', 31, 9, 'نو موسی د شریعت حکمونه ولیکل او هغو لاوي کاهنانو ته چې د څښتن د لوظ صندوق یې انتقالاوه او د اسراییلو ټولو مشرانو ته یې ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_9.mp3', '', 1761754199, 1761754199),
(49457, 'Deuteronomy 31:10', 'Deuteronomy', 31, 10, 'موسی هغوی ته داسې امر وکړ: «د هر اووم کال په اخر کې یعنې کله چې د پورونو د بخښلو کال راځي هغه د جونګړو په اختر کې په لوړ اواز لولئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_10.mp3', '', 1761754199, 1761754199),
(49458, 'Deuteronomy 31:11', 'Deuteronomy', 31, 11, 'دا په هغه وخت کې د اسراییلو قوم ته لولئ کله چې هغوی د څښتن خدای د عبادت دپاره هغه ځای ته راځي چې هغه یې ټاکي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_11.mp3', '', 1761754199, 1761754199),
(49459, 'Deuteronomy 31:12', 'Deuteronomy', 31, 12, 'ټول سړي، ښځې او ماشومان او هغه پردي خلک چې ستاسو په ښارونو کې اوسیږي راوغواړئ، ترڅو هرڅوک هغه واوري او د خپل څښتن خدای درناوی کول زده کړي او په وفادارۍ سره د هغه د ټولو قوانینو څخه پیروي وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_12.mp3', '', 1761754199, 1761754199),
(49460, 'Deuteronomy 31:13', 'Deuteronomy', 31, 13, 'په دې ډول به ستاسو اولاده چې د خپل څښتن خدای شریعت یې نه دی اورېدلی، واوري. نو هغوی به ټول ژوند په هغه خاوره کې چې تاسو به یې زر د اردن د سیند په بله غاړه ونیسئ، د څښتن اطاعت کول زده کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_13.mp3', '', 1761754199, 1761754199),
(49461, 'Deuteronomy 31:14', 'Deuteronomy', 31, 14, 'بیا څښتن موسی ته وویل: «ستا د مړینې وخت رانژدې شوی دی. یوشع راوغواړه او سپېڅلې خېمې ته یې راوله، ترڅو هغه د اسراییلو مشر وټاکم.» موسی او یوشع خېمې ته لاړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_14.mp3', '', 1761754199, 1761754199),
(49462, 'Deuteronomy 31:15', 'Deuteronomy', 31, 15, 'او څښتن هغوی ته هلته د ستنې په شان ورېځې کې چې د خېمې د دروازې په سر باندې ولاړه وه، ښکاره شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_15.mp3', '', 1761754199, 1761754199),
(49463, 'Deuteronomy 31:16', 'Deuteronomy', 31, 16, 'څښتن موسی ته وویل: «ته به زر مړ شې او ستا د مړینې څخه وروسته به خلک زما سره بې وفایي وکړي او هغه لوظ به مات کړي چې ما د هغوی سره کړی دی. هغوی به ما پرېږدي او په هغه هېواد کې به چې هغوی ورداخلیږي د پردیو خدایانو عبادت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_16.mp3', '', 1761754199, 1761754199),
(49464, 'Deuteronomy 31:17', 'Deuteronomy', 31, 17, 'کله چې داسې وشي، نو زه به په هغوی باندې په قهر شم، د هغوی څخه به مخ واړوم او هغوی به تباه شي. ډېر هیبتناکه افتونه به په هغوی باندې نازل شي او هغوی به په دې پوه شي چې دا پېښې ځکه ورباندې راځي چې زه یعنې د هغوی خدای نور د هغوی سره نه یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_17.mp3', '', 1761754199, 1761754199),
(49465, 'Deuteronomy 31:18', 'Deuteronomy', 31, 18, 'په هغه وخت کې به زه د هغوی سره د مرستې کولو څخه انکار وکړم، ځکه چې هغوی بد کار کړی دی او د نورو خدایانو عبادت یې کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_18.mp3', '', 1761754199, 1761754199),
(49466, 'Deuteronomy 31:19', 'Deuteronomy', 31, 19, 'موسی او یوشع، اوس دا روحاني سندره ولیکئ. موسی، هغه اسراییلیانو ته ورزده کړه. که چېرې هغوی دا سندره زده کړه، نو هغوی به پوه شي چې زه ورڅخه څه غواړم چې ویې کړي او هغوی سره به کومه بهانه نه وي چې زما د امر څخه سرغړونه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_19.mp3', '', 1761754199, 1761754199),
(49467, 'Deuteronomy 31:20', 'Deuteronomy', 31, 20, 'لکه څنګه چې مې د هغوی د نیکونو سره وعده کړې ده، زه به هغوی دې غني او حاصلخېزې ځمکې ته بوځم. څومره خواړه چې هغوی غواړي هلته به ورته ورسیږي او هغوی به ارام ژوند لري. خو هغوی به زما څخه مخ واړوي او د نورو خدایانو عبادت به کوي. هغوی به زما څخه منکر شي او زما لوظ به مات کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_20.mp3', '', 1761754199, 1761754199),
(49468, 'Deuteronomy 31:21', 'Deuteronomy', 31, 21, 'او ډېر هیبتناکه افتونه به ورباندې نازل شي. خو بیاهم دا سندره به ویل کیږي او دا به د هغوی په ضد یوه نښه وي. حتی اوس، مخکې له دې چې زه هغوی هغه هېواد ته بوځم چې ما یې د ورکولو وعده ورسره کړې ده، زه پوهېږم چې هغوی څه پلان سنجوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_21.mp3', '', 1761754199, 1761754199),
(49469, 'Deuteronomy 31:22', 'Deuteronomy', 31, 22, 'په هماغه ورځ موسی سندره ولیکله او د اسراییلو قوم ته یې ورزده کړله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_22.mp3', '', 1761754199, 1761754199),
(49470, 'Deuteronomy 31:23', 'Deuteronomy', 31, 23, 'بیا څښتن د نون زوی یوشع مشر وټاکه او ورته ویې ویل: «قوي او زړور اوسه. ته به د اسراییلو قوم هغه هېواد ته بوځې چې ما یې د هغوی سره وعده کړې ده او زه به ستا سره مل یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_23.mp3', '', 1761754199, 1761754199),
(49471, 'Deuteronomy 31:24', 'Deuteronomy', 31, 24, 'موسی د شریعت حکمونه په کتاب کې ولیکل او پام یې کاوه چې څه شی ورڅخه پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_24.mp3', '', 1761754199, 1761754199),
(49472, 'Deuteronomy 31:25', 'Deuteronomy', 31, 25, 'کله چې هغه وزګار شو، نو هغه هغو لاوي کاهنانو ته چې د څښتن د لوظ صندوق یې انتقالاوه داسې وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_25.mp3', '', 1761754199, 1761754199),
(49473, 'Deuteronomy 31:26', 'Deuteronomy', 31, 26, '«د شریعت دا کتاب یوسئ او د خپل څښتن خدای د لوظ د صندوق په څنګ کې یې کېږدئ. دا کتاب به د دې خبرې یو ثبوت وي چې تاسو پوهېږئ چې څښتن ستاسو څخه څه غواړي چې ویې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_26.mp3', '', 1761754199, 1761754199),
(49474, 'Deuteronomy 31:27', 'Deuteronomy', 31, 27, 'زه په دې پوهېږم چې هغوی څومره سرزوري او سرکښ خلک دي. هغوی زما د ژوندانه په دوران کې د څښتن په وړاندې سرکښي کړې ده او زما د مړینې څخه وروسته به نور هم سرکښه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_27.mp3', '', 1761754199, 1761754199),
(49475, 'Deuteronomy 31:28', 'Deuteronomy', 31, 28, 'خپل ټول قبیلوي مشران او مامورین زما په مخکې راټول کړئ، ترڅو هغوی ته دا خبرې وکړم. زه به ځمکه او اسمان د اسراییلو د قوم په وړاندې خپل شاهدان ونیسم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_28.mp3', '', 1761754199, 1761754199),
(49476, 'Deuteronomy 31:29', 'Deuteronomy', 31, 29, 'زه په دې پوهېږم چې زما د مرګ څخه وروسته به قوم بیخي فاسد شي او د هغې لارې څخه به چې ما ورته حکم کړی دی وګرځي. د وخت په تېرېدلو سره به هغوی د افت سره مخامخ شي، ځکه چې هغوی به څښتن د هغو کارونو په سبب چې هغه منع کړي دي په قهر کړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_29.mp3', '', 1761754199, 1761754199),
(49477, 'Deuteronomy 31:30', 'Deuteronomy', 31, 30, 'بیا موسی ټوله سندره وویله او د اسراییلو ټول قوم ورته غوږ نیولی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy31_verse_30.mp3', '', 1761754199, 1761754199),
(49478, 'Jeremiah 13:1', 'Jeremiah', 13, 1, 'مالِک خُدائ ما ته وفرمائيل چې، ”لاړ شه او د خپل ځان دپاره د کتان لنګ واخله او د ملا نه يې تاؤ کړه خو چې په اوبو کښې درنه لوند نۀ شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_1.mp3', '', 1761754199, 1761754199),
(49479, 'Jeremiah 13:2', 'Jeremiah', 13, 2, 'نو د مالِک خُدائ د هدايت په مطابق ما لنګ واخستو او د ملا نه مې تاؤ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_2.mp3', '', 1761754199, 1761754199),
(49480, 'Jeremiah 13:3', 'Jeremiah', 13, 3, 'نو بيا په دوېم ځل د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_3.mp3', '', 1761754199, 1761754199),
(49481, 'Jeremiah 13:4', 'Jeremiah', 13, 4, '”کوم لنګ چې تا اخستے او تاؤ کړے دے اوس د فرات سيند ته لاړ شه او هلته د ګټ په سورى کښې يې پټ کړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_4.mp3', '', 1761754199, 1761754199),
(49482, 'Jeremiah 13:5', 'Jeremiah', 13, 5, 'نو د مالِک خُدائ د هدايت په مطابق زۀ لاړم او لنګ مې هلته پټ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_5.mp3', '', 1761754199, 1761754199),
(49483, 'Jeremiah 13:6', 'Jeremiah', 13, 6, 'څۀ موده وروستو بيا مالِک خُدائ ما ته وفرمائيل، ”د فرات سيند ته لاړ شه او هغه لنګ بيا راواخله کوم چې ما درته فرمائيلى وُو چې هلته يې پټ کړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_6.mp3', '', 1761754199, 1761754199),
(49484, 'Jeremiah 13:7', 'Jeremiah', 13, 7, 'نو بيا زۀ لاړم او هغه ځائ نه مې راوويستو په کوم ځائ کښې چې ما لنګ پټ کړے وو، خو ومې ليدو چې دا بلکل سخا شوے وو او د هيڅ کار نۀ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_7.mp3', '', 1761754199, 1761754199),
(49485, 'Jeremiah 13:8', 'Jeremiah', 13, 8, 'نو د مالِک خُدائ کلام بيا په ما نازل شو چې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_8.mp3', '', 1761754199, 1761754199),
(49486, 'Jeremiah 13:9', 'Jeremiah', 13, 9, '”لکه څنګه چې دا لنګ سخا شوے دے دغه رنګ به زۀ د يهوداه او د يروشلم لوئ غرور سخا کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_9.mp3', '', 1761754199, 1761754199),
(49487, 'Jeremiah 13:10', 'Jeremiah', 13, 10, 'دې بدکاره خلقو چا چې زما د کلام د اورېدو نه اِنکار وکړو، او د خپلو سرکشه زړونو يې ومنل او د نورو معبودانو عبادت او خِدمت يې شروع کړو، نو د هغوئ حالت به د دې سخا شوے لنګ په شان وى چې د هيڅ کار نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_10.mp3', '', 1761754199, 1761754199),
(49488, 'Jeremiah 13:11', 'Jeremiah', 13, 11, 'لکه څنګه چې لنګ د انسان د ملا نه کلک تاو وى، نو دغه شان ما د اِسرائيل او د يهوداه خلق خپل ځان سره وتړل چې دوئ زما د نوم د شُهرت، تعريف او عزت باعث وى. خو هغوئ زما تابعدارى ونۀ کړه.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_11.mp3', '', 1761754199, 1761754199),
(49489, 'Jeremiah 13:12', 'Jeremiah', 13, 12, 'نو هغوئ ته ووايه چې، مالِک خُدائ د بنى اِسرائيلو خُدائ پاک فرمائى، ”ستا د ميو ټولې چاټۍ دې د ميو نه ډکې شى. او بيا دوئ جواب ور کړو چې، بې‌شکه، هره يوه چاټۍ به د ميو نه ډکه شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_12.mp3', '', 1761754199, 1761754199),
(49490, 'Jeremiah 13:13', 'Jeremiah', 13, 13, 'نو بيا تۀ هغوئ ته ووايه چې، مالِک خُدائ فرمائى زۀ به د دې مُلک په ټولو خلقو او د داؤد په نسل، په بادشاهانو، او اِمامانو، پېغمبرانو دومره مے وڅښم چې ښۀ نشه شى او په هر هغه چا چې په يروشلم کښې اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_13.mp3', '', 1761754199, 1761754199),
(49491, 'Jeremiah 13:14', 'Jeremiah', 13, 14, 'نو بيا به زۀ هغوئ په خپلو کښې سره وجنګومه تر دې چې مور پلار او بچى به په خپلو کښې يو بل زره زره کړى. او زۀ به په هغوئ هيڅ قسم رحم او ترس ونۀ کړم. او هيڅ څيز به ما د هغوئ د تباه کولو نه منع نۀ کړى.“ دا د مالِک خُدائ وينا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_14.mp3', '', 1761754199, 1761754199),
(49492, 'Jeremiah 13:15', 'Jeremiah', 13, 15, 'په غور او احتياط سره واورئ او مغروره کېږئ مه. ځکه چې مالِک خُدائ دا فرمائيلى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_15.mp3', '', 1761754199, 1761754199),
(49493, 'Jeremiah 13:16', 'Jeremiah', 13, 16, 'د دې نه مخکښې چې ډېر ناوخته شى مالِک خُدائ، خپل خُدائ پاک ته جلال ورکړئ. او هغه وپېژنئ د دې نه وړاندې چې هغه درباندې تيارۀ راولى، او تاسو تيندک وخورئ او په تورو تيارو غرونو کښې راوغورزېږئ. او د هغه نُور چې تاسو يې په انتظار کښې يئ نو مالِک خُدائ به هغه په تورو تيارو بدل کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_16.mp3', '', 1761754199, 1761754199),
(49494, 'Jeremiah 13:17', 'Jeremiah', 13, 17, 'کۀ تاسو اوس هم غوږ ونۀ نيسئ، نو زۀ به ستاسو د غرور په وجه پټ پټ وژاړم. زما سترګې به ترخه ژړا وکړى او ډکې به شى او اوښکې به ترې بهيږى. ځکه چې دشمن به د مالِک خُدائ قوم لکه د يوې رمې په شان راګېر کړى او قېدولو له به يې بوځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_17.mp3', '', 1761754199, 1761754199),
(49495, 'Jeremiah 13:18', 'Jeremiah', 13, 18, 'مالِک خُدائ ما ته وفرمائيل چې، ”بادشاه او د هغۀ مور ته ووايه چې، د تخت نه راکوز شه او په خاورو کښې کښېنه، ځکه چې ستا د شان او شوکت تاجونه به زر ستا د سر نه راوغورزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_18.mp3', '', 1761754199, 1761754199),
(49496, 'Jeremiah 13:19', 'Jeremiah', 13, 19, 'د نجب ښارونو دروازې به بند کړے شى او څوک به هم هغه نۀ شى کولاولے. د يهوداه ټول خلق به جلاوطن کړے شى او يو به هم بچ نۀ شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_19.mp3', '', 1761754199, 1761754199),
(49497, 'Jeremiah 13:20', 'Jeremiah', 13, 20, 'خپلې سترګې اوچتې کړه او هغه فوج وګوره چې د شمال د خوا نه راروان دے. ستا هغه ښکلې رَمې اوس چرته دى چې ما تا ته سپارلې وې؟ ستا هغه ګډان چرته دى چې تا به پرې فخر کولو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_20.mp3', '', 1761754199, 1761754199),
(49498, 'Jeremiah 13:21', 'Jeremiah', 13, 21, 'تۀ به په هغه ورځ څۀ وائې کله چې مالِک خُدائ په تا هغه خلق حکمرانان مقرر کړى کوم خلق چې تا خپله ډله جوړه کړې وه؟ لکه څنګه چې د ښځې د ماشوم د پېدا کېدو وخت وى نو تۀ به په دغه شان تکليف کښې شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_21.mp3', '', 1761754199, 1761754199),
(49499, 'Jeremiah 13:22', 'Jeremiah', 13, 22, 'کۀ تۀ چرې د خپل ځان نه تپوس وکړې چې دا هر څۀ ما سره ولې کيږى؟ نو دا ستا د ډېرو ګناهونو په وجه تا سره وشول. نو ځکه ستا نه جامې وويستلے شوې او هغه حمله کوونکو فوجيانو تا سره په زور زنا وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_22.mp3', '', 1761754199, 1761754199),
(49500, 'Jeremiah 13:23', 'Jeremiah', 13, 23, 'ولې د ايتهوپيا يو سړے د خپلې څرمنې رنګ بدلولے شى؟ يا يو پړانګ د ځان نه خالونه لرې کولے شى څۀ؟ نه کله هم نه، هم دغه رنګ تۀ په بدو عملونو دومره عادت شوے يې چې تۀ کله هم نېک کارونه نۀ شې کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_23.mp3', '', 1761754199, 1761754199),
(49501, 'Jeremiah 13:24', 'Jeremiah', 13, 24, 'زۀ به تاسو لکه د بوسو په شان چې د صحرا هوا په مخه اخستې وى خوارۀ وارۀ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_24.mp3', '', 1761754199, 1761754199),
(49502, 'Jeremiah 13:25', 'Jeremiah', 13, 25, 'مالِک خُدائ فرمائى چې، دا ستا قسمت دے، هغه برخه چې ما ستا دپاره مقرر کړې ده. ځکه چې تا زۀ هېر کړے يم او په دروغژنو معبودانو دې يقين کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_25.mp3', '', 1761754199, 1761754199),
(49503, 'Jeremiah 13:26', 'Jeremiah', 13, 26, 'اے قومه، زۀ به په خپله ستاسو نه جامې وکاږم چې تاسو لغړ کړم او شرمګاه مو ښکاره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_26.mp3', '', 1761754199, 1761754199),
(49504, 'Jeremiah 13:27', 'Jeremiah', 13, 27, 'ما ستاسو زناکارى او د نفس خواهشات، ما ستاسو په بې‌شرمۍ سره د بُتانو عبادت په لوړو او ژورو باندې وليدلو. په تاسو دې افسوس وى، اے يروشلمه. ترڅو پورې به تاسو داسې حرام کاره او ناپاکه يئ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah13_verse_27.mp3', '', 1761754199, 1761754199),
(49505, 'Psalms 46:1', 'Psalms', 46, 1, 'خدای سرپناه دی زمونږ، قوت دی زمونږ د سختۍ وخت کې زمونږ مرستې ته حاضر دی همېش', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_1.mp3', '', 1761754199, 1761754199),
(49506, 'Psalms 46:2', 'Psalms', 46, 2, 'مونږ به ونه وېرېږو، که ځمکه ولړزیږي غرونه راپرېوځي د بحرونو تل ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_2.mp3', '', 1761754199, 1761754199),
(49507, 'Psalms 46:3', 'Psalms', 46, 3, 'که دریابونه وغړمبیږي، توفاني هم شي او له دې زوره غرونه ولړزیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_3.mp3', '', 1761754199, 1761754199),
(49508, 'Psalms 46:4', 'Psalms', 46, 4, 'داسې یو سیند دی چې د خدای ښار ته خوښي راولي سپېڅلی کور چېرته چې دی خدای تعالی په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_4.mp3', '', 1761754199, 1761754199),
(49509, 'Psalms 46:5', 'Psalms', 46, 5, 'خدای په دې ښار کې اوسي، هېڅکله دا وران به نه شي هغه به یې کړي ساتنه د سباوون په وخت کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_5.mp3', '', 1761754199, 1761754199),
(49510, 'Psalms 46:6', 'Psalms', 46, 6, 'قومونه سخت دي په غوغا او پاچاهۍ لړزیږي خدای کړي اواز لکه د تندر ویلي کیږي دنیا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms46_verse_6.mp3', '', 1761754199, 1761754199);